package ru.neverland.townyarmy;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.locks.*;
import ru.neverland.core.*;import static ru.neverland.townyarmy.ArmyModel.*;import static ru.neverland.townyarmy.ArmyRepositorySmoke.done;
public final class ArmyEquipmentStockSmoke {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}interface Work{void run()throws Exception;}static void denied(Work w,String why)throws Exception{boolean no=false;try{w.run();}catch(Exception e){no=true;}check(no,why);}
 @SuppressWarnings("unchecked")static ReentrantLock writer(Path path)throws Exception{var f=AtomicFiles.class.getDeclaredField("writers");f.setAccessible(true);return ((ConcurrentMap<Path,ReentrantLock>)f.get(null)).computeIfAbsent(path.toAbsolutePath().normalize(),p->new ReentrantLock());}
 public static void main(String[] args)throws Exception{
  Path path=Files.createTempDirectory("army-kit-stock-").resolve("army.yml");var r=new ArmyRepository(path,100);r.load();UUID town=UUID.randomUUID(),player=UUID.randomUUID(),id=UUID.randomUUID();var cost=Map.of("metal",7000L);var d=r.draft();d.imported=d.handoff=true;d.cities.put(town,City.empty(town).stock(Map.of("metal",10000L)));done(r.commit(d));
  check(r.equipmentReceipt(town,id,player,cost).equals("NONE"),"unfunded receipt has no stock effect");check(done(r.fundEquipment(town,id,player,cost,1))&&r.state().cities().get(town).stock().get("metal")==3000L,"equipment budget and immutable receipt share one ACK");check(done(r.fundEquipment(town,id,player,cost,2))&&r.state().cities().get(town).stock().get("metal")==3000L,"same funded request cannot charge twice");denied(()->r.equipmentReceipt(town,id,UUID.randomUUID(),cost),"recipient substitution refused");denied(()->r.equipmentReceipt(UUID.randomUUID(),id,player,cost),"city substitution refused");denied(()->r.equipmentReceipt(town,id,player,Map.of("metal",6000L)),"cost substitution refused");check(!done(r.fundEquipment(town,UUID.randomUUID(),player,cost,3)),"insufficient stock leaves no partial debit");done(r.close());var restart=new ArmyRepository(path,100);restart.load();check(restart.equipmentReceipt(town,id,player,cost).equals("SPENT"),"real restart retains funded receipt");
  var lock=writer(path);CompletionStage<Void> refund;lock.lock();try{refund=restart.returnEquipment(town,id,player,cost,4);try(var guard=SuiteState.guard()){check(!refund.toCompletableFuture().isDone()&&restart.state().cities().get(town).stock().get("metal")==3000L&&restart.equipmentReceipt(town,id,player,cost).equals("SPENT"),"refund is not advertised before actual file ACK");}}finally{lock.unlock();}done(refund);check(restart.state().cities().get(town).stock().get("metal")==10000L&&restart.equipmentReceipt(town,id,player,cost).equals("RETURNED"),"exact refund and terminal receipt publish together");done(restart.returnEquipment(town,id,player,cost,5));check(restart.state().cities().get(town).stock().get("metal")==10000L,"refund replay cannot mint resources");denied(()->done(restart.fundEquipment(town,id,player,cost,6)),"returned ID cannot fund another kit");done(restart.returnEquipment(town,UUID.randomUUID(),player,cost,7));check(restart.state().cities().get(town).stock().get("metal")==10000L,"never-funded cancellation cannot credit stock");done(restart.close());System.out.println("ArmyEquipmentStockSmoke PASS "+checks+" checks");
 }
}
